import { createAudioPlayer, setAudioModeAsync, type AudioPlayer } from 'expo-audio';

import { useSettings } from '@/store/settings';

/**
 * Sound, built the same way `lib/haptics.ts` is: every call routes through here
 * so the Settings toggles actually silence it, and the vocabulary is small and
 * fixed rather than grown one `play('...')` at a time.
 *
 * Two separate switches, because they are two separate annoyances: music is the
 * thing someone turns off on a bus, effects are the thing they keep.
 *
 * Every file is generated by `scripts/sesler.ts` — nothing here is licensed
 * from anywhere, same rule the images follow.
 */

const FILES = {
  sek: require('../../assets/sounds/sek.m4a'),
  kir: require('../../assets/sounds/kir.m4a'),
  top: require('../../assets/sounds/top.m4a'),
  altin: require('../../assets/sounds/altin.m4a'),
  bitti: require('../../assets/sounds/bitti.m4a'),
  rekor: require('../../assets/sounds/rekor.m4a'),
} as const;

export type Sfx = keyof typeof FILES;

/**
 * The floor between two plays of the same sound, in ms. A bounce is the only
 * one that needs it — forty balls hitting walls produce dozens of collisions a
 * second, and a phone speaker asked to restart the same clip that often
 * produces a buzz, not a rhythm. The others are once-an-event by nature.
 */
const MIN_GAP: Partial<Record<Sfx, number>> = { sek: 55 };

let players: Partial<Record<Sfx, AudioPlayer>> = {};
let musicPlayer: AudioPlayer | null = null;
const lastPlayedAt: Partial<Record<Sfx, number>> = {};

/**
 * Loads every clip once, up front. Called from the root layout: creating a
 * player on the first bounce would drop that bounce, and doing it per-play
 * would leak one native player per collision.
 */
export async function initAudio(): Promise<void> {
  if (Object.keys(players).length > 0) return;

  // Plays through the silent switch being wrong for a game, and ducking other
  // apps would be rude for something this quiet — it mixes instead, so a
  // podcast keeps playing over it.
  await setAudioModeAsync({ playsInSilentMode: false, shouldPlayInBackground: false });

  for (const name of Object.keys(FILES) as Sfx[]) {
    players[name] = createAudioPlayer(FILES[name]);
  }
}

export function playSfx(name: Sfx): void {
  if (!useSettings.getState().sfxEnabled) return;

  const player = players[name];
  if (!player) return;

  const gap = MIN_GAP[name];
  if (gap !== undefined) {
    const now = Date.now();
    if (now - (lastPlayedAt[name] ?? 0) < gap) return;
    lastPlayedAt[name] = now;
  }

  // Rewind rather than overlap: one player per clip keeps the native side
  // bounded, and for sounds this short a restart is indistinguishable from a
  // second voice.
  player.seekTo(0);
  player.play();
}

export function startMusic(): void {
  if (!useSettings.getState().musicEnabled) return;
  if (musicPlayer) {
    musicPlayer.play();
    return;
  }

  musicPlayer = createAudioPlayer(require('../../assets/sounds/muzik.m4a'));
  musicPlayer.loop = true;
  musicPlayer.volume = 0.85;
  musicPlayer.play();
}

export function stopMusic(): void {
  musicPlayer?.pause();
}
